from fastapi.sse import ServerSentEvent
from pydantic import ValidationError

def test_sse_validation():
    # Valid event
    try:
        ServerSentEvent(event="test", id="123")
        print("Valid event passed")
    except ValidationError as e:
        print(f"Valid event failed: {e}")

    # Invalid event (newline)
    try:
        ServerSentEvent(event="test\nnewline")
        print("Invalid event (newline) passed - FAIL")
    except ValidationError as e:
        print(f"Invalid event (newline) caught: {e}")

    # Invalid id (newline)
    try:
        ServerSentEvent(id="123\nnewline")
        print("Invalid id (newline) passed - FAIL")
    except ValidationError as e:
        print(f"Invalid id (newline) caught: {e}")

    # Invalid id (null char)
    try:
        ServerSentEvent(id="123\0null")
        print("Invalid id (null char) passed - FAIL")
    except ValidationError as e:
        print(f"Invalid id (null char) caught: {e}")

if __name__ == "__main__":
    test_sse_validation()

